import {
  Column,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import type { FinancingFile } from './financing-file.entity.js';

/**
 * Scheduled instalment (principal + interest), regenerated by
 * `POST …/schedule` while no repayment exists. Paid amounts, status and days
 * late are never stored: computed from the repayments at read time.
 */
@Index('UQ_financing_instalments_number', ['fileId', 'number'], { unique: true })
@Entity('financing_instalments')
export class FinancingInstalment {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @ManyToOne('FinancingFile', { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'file_id' })
  file?: FinancingFile;

  @Column({ name: 'file_id', type: 'uuid' })
  fileId: string;

  @Column({ type: 'int' })
  number: number;

  @Column({ name: 'due_date', type: 'date' })
  dueDate: string;

  @Column({ name: 'principal_fcfa', type: 'int' })
  principalFcfa: number;

  @Column({ name: 'interest_fcfa', type: 'int' })
  interestFcfa: number;
}
